contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 _value) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(balBefore >= _value);

        bool reverted;
        bool success;
        bool s = c.burn(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            success = s;
            reverted = false;
        }

        assert(reverted || (success == true && c.totalSupply() == supplyBefore - _value));
    }
}

