        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 _value) internal {
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        vm.assume(balBefore >= _value);
        bool reverted;
        bool success;
        try c.burn(_value) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (success == true && c.totalSupply() == supplyBefore - _value));
